    @Test
    public void flagValueIsShownOnCard() {
        Note n = addNote("1");
        flagCardForNote(n, 1);

        long cardId = n.cards().get(0).getId();

        CardBrowser b = getBrowserWithNoNewCards();
        Map<String, String> cardProperties = b.getPropertiesForCardId(cardId);

